# Revisão e Especificação Técnica — Frente 3: `VipShop`

Esta resposta é **exclusivamente textual** e não executa ferramentas, comandos, escritas em disco ou alterações em arquivos do projeto. O código abaixo foi projetado para entrega direta à revisão do **Codex**, em conformidade com o ecossistema MonsterCrypt / Crypt Royale.

---

## 1. Componente React ES: `VipShop.jsx`

```jsx
import React, { useState, useMemo, useCallback } from 'react';
import { Crown, Shield, Sparkles, Clock, AlertTriangle, CheckCircle, Info } from 'lucide-react';
import { VIP_TIERS, vipAccess } from './vip.js';
import './VipShop.css';

/**
 * Utilitário para formatar timestamps para o fuso America/Sao_Paulo
 */
function formatSaoPauloDate(timestamp) {
  if (!timestamp) return null;
  try {
    const dateObj = timestamp?.toDate ? timestamp.toDate() : new Date(timestamp);
    if (isNaN(dateObj.getTime())) return null;
    return new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(dateObj);
  } catch {
    return null;
  }
}

/**
 * Fallback seguro para geração de UUID caso crypto.randomUUID não esteja presente
 */
function safeRandomUUID() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Tabela de metadados visuais e mecânicos oficiais por Tier
 */
const TIER_SPECS = [
  {
    id: 'bronze',
    name: 'VIP Bronze',
    icon: Shield,
    themeClass: 'vip-card--bronze',
    pveMinutes: 18,
    pvpMinutes: 20,
    defaultPriceGold: 500
  },
  {
    id: 'prata',
    name: 'VIP Prata',
    icon: Sparkles,
    themeClass: 'vip-card--prata',
    pveMinutes: 16,
    pvpMinutes: 20,
    defaultPriceGold: 1000
  },
  {
    id: 'ouro',
    name: 'VIP Ouro',
    icon: Crown,
    themeClass: 'vip-card--ouro',
    pveMinutes: 15,
    pvpMinutes: 20,
    defaultPriceGold: 2000
  }
];

export default function VipShop({
  profile,
  authenticated = false,
  ready = false,
  busy = false,
  clockNow = null,
  onBuy
}) {
  // Estado local para controle de confirmação inline e ciclo do requestId
  const [confirmingTierId, setConfirmingTierId] = useState(null);
  const [activeRequestId, setActiveRequestId] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [feedback, setFeedback] = useState(null);

  // Status de VIP atual calculado de forma idempotente via vipAccess
  const vipStatus = useMemo(() => {
    if (!profile || clockNow == null || typeof vipAccess !== 'function') {
      return { active: false, tier: null, expiresAt: null };
    }
    try {
      const res = vipAccess(profile, clockNow);
      return res && typeof res === 'object'
        ? res
        : { active: false, tier: null, expiresAt: null };
    } catch (err) {
      console.warn('[VipShop] Erro ao avaliar vipAccess:', err);
      return { active: false, tier: null, expiresAt: null };
    }
  }, [profile, clockNow]);

  // Data de expiração formatada em São Paulo (apenas se realmente ativo)
  const formattedExpiresAt = useMemo(() => {
    if (!vipStatus.active || !vipStatus.expiresAt) return null;
    return formatSaoPauloDate(vipStatus.expiresAt);
  }, [vipStatus]);

  // Mesclagem com VIP_TIERS importado de ./vip.js
  const tiers = useMemo(() => {
    return TIER_SPECS.map((spec) => {
      let resolvedPrice = spec.defaultPriceGold;
      if (VIP_TIERS) {
        if (Array.isArray(VIP_TIERS)) {
          const match = VIP_TIERS.find((t) => t.id === spec.id);
          if (match?.priceGold != null) resolvedPrice = match.priceGold;
        } else if (typeof VIP_TIERS === 'object' && VIP_TIERS[spec.id]?.priceGold != null) {
          resolvedPrice = VIP_TIERS[spec.id].priceGold;
        }
      }
      return {
        ...spec,
        priceGold: resolvedPrice
      };
    });
  }, []);

  // Seleciona tier para confirmação inline e isolamento estrito de requestId
  const handleOpenConfirm = useCallback((tierId) => {
    setFeedback(null);
    if (confirmingTierId !== tierId) {
      // Trocar de tier cancela a intenção anterior e gera um novo requestId
      setConfirmingTierId(tierId);
      setActiveRequestId(safeRandomUUID());
    }
  }, [confirmingTierId]);

  // Cancela o modal inline
  const handleCancelConfirm = useCallback(() => {
    setConfirmingTierId(null);
    setActiveRequestId(null);
    setFeedback(null);
  }, []);

  // Confirmação final da compra delegada ao componente pai
  const handleConfirmPurchase = useCallback(async (tier) => {
    if (isSubmitting || busy || !ready || !authenticated || !profile || clockNow == null) {
      return;
    }

    // Garante que haja um requestId fixado para esta tentativa
    const reqId = activeRequestId || safeRandomUUID();
    if (!activeRequestId) setActiveRequestId(reqId);

    setIsSubmitting(true);
    setFeedback(null);

    try {
      if (typeof onBuy !== 'function') {
        throw new Error('Manipulador onBuy não configurado no componente pai.');
      }

      // onBuy é assíncrono e deve retornar boolean (true = sucesso no Firestore)
      const success = await onBuy(tier.id, reqId);

      if (success) {
        setFeedback({
          type: 'success',
          message: `${tier.name} adquirido com sucesso!`
        });
        setConfirmingTierId(null);
        // Sucesso consome o ID; gera um novo para compras futuras
        setActiveRequestId(safeRandomUUID());
      } else {
        // Falha / resposta perdida: mantém o MESMO requestId para retry idempotente
        setFeedback({
          type: 'error',
          message: 'A transação não foi confirmada. Tente novamente (o mesmo identificador de segurança foi mantido).'
        });
      }
    } catch (err) {
      setFeedback({
        type: 'error',
        message: err?.message || 'Falha na comunicação com o servidor.'
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [isSubmitting, busy, ready, authenticated, profile, clockNow, activeRequestId, onBuy]);

  // Verificações de bloqueio global
  const isClockUnavailable = clockNow == null;
  const isGuest = !authenticated || !profile;
  const isActionBlocked = isClockUnavailable || isGuest || busy || !ready || isSubmitting;

  return (
    <section className="vip-shop-container" aria-label="Loja de Planos VIP">
      <header className="vip-shop-header">
        <h2 className="vip-shop-title">Assinaturas VIP</h2>
        <p className="vip-shop-subtitle">
          Benefícios exclusivos de recarga energética e vantagens cosméticas.
        </p>

        {/* Notificação de relógio indisponível */}
        {isClockUnavailable && (
          <div className="vip-shop-banner vip-shop-banner--warning" role="alert">
            <Clock className="vip-banner-icon" aria-hidden="true" size={20} />
            <span>
              <strong>Relógio em sincronização:</strong> É necessário estar conectado para validar
              o horário oficial de Brasília e adquirir planos VIP.
            </span>
          </div>
        )}

        {/* Notificação para usuário não autenticado / guest safe */}
        {!isClockUnavailable && isGuest && (
          <div className="vip-shop-banner vip-shop-banner--info" role="status">
            <Info className="vip-banner-icon" aria-hidden="true" size={20} />
            <span>Conecte-se com sua conta para ativar ou renovar seu plano VIP.</span>
          </div>
        )}

        {/* Feedback de sucesso ou erro */}
        {feedback && (
          <div
            className={`vip-shop-banner vip-shop-banner--${feedback.type}`}
            role={feedback.type === 'error' ? 'alert' : 'status'}
          >
            {feedback.type === 'success' ? (
              <CheckCircle className="vip-banner-icon" aria-hidden="true" size={20} />
            ) : (
              <AlertTriangle className="vip-banner-icon" aria-hidden="true" size={20} />
            )}
            <span>{feedback.message}</span>
          </div>
        )}

        {/* Status de VIP Ativo Atual */}
        {vipStatus.active && (
          <div className="vip-active-indicator" role="status">
            <Crown size={18} className="vip-active-icon" aria-hidden="true" />
            <span>
              Você possui <strong>Plano {vipStatus.tier?.toUpperCase()}</strong> ativo até{' '}
              <strong>{formattedExpiresAt} (Horário de Brasília)</strong>.
            </span>
          </div>
        )}
      </header>

      {/* Grid de Cards dos 3 Tiers */}
      <div className="vip-cards-grid">
        {tiers.map((tier) => {
          const IconComponent = tier.icon;
          const isCurrentActiveTier = vipStatus.active && vipStatus.tier === tier.id;
          const isOtherTierActive = vipStatus.active && vipStatus.tier !== tier.id;
          const isConfirmingThis = confirmingTierId === tier.id;

          // Regra: outro tier fica desabilitado até expirar o atual
          const isTierDisabled = isActionBlocked || isOtherTierActive;

          return (
            <article
              key={tier.id}
              className={`vip-card ${tier.themeClass} ${isCurrentActiveTier ? 'vip-card--active' : ''}`}
            >
              <div className="vip-card-header">
                <div className="vip-badge-icon" aria-hidden="true">
                  <IconComponent size={28} />
                </div>
                <h3 className="vip-tier-name">{tier.name}</h3>
                {isCurrentActiveTier && (
                  <span className="vip-tag-active">Ativo</span>
                )}
              </div>

              <div className="vip-price-block">
                <span className="vip-price-value">{tier.priceGold.toLocaleString('pt-BR')} Gold</span>
                <span className="vip-price-period">Validade de 7 dias</span>
                <span className="vip-no-renewal-badge">Sem renovação automática</span>
              </div>

              <ul className="vip-benefits-list" aria-label={`Vantagens do ${tier.name}`}>
                <li>
                  <strong>Recarga PvE:</strong> a cada {tier.pveMinutes} min (padrão 20 min)
                </li>
                <li>
                  <strong>Recarga PvP:</strong> a cada {tier.pvpMinutes} min (todos os tiers)
                </li>
                <li>
                  <strong>Vantagens:</strong> Título e efeitos cosméticos integrados
                </li>
              </ul>

              {/* Área de Ação e Confirmação Inline */}
              <div className="vip-action-container">
                {isConfirmingThis ? (
                  <div className="vip-inline-confirm" role="dialog" aria-label={`Confirmar ${tier.name}`}>
                    <p className="vip-confirm-text">
                      Confirmar {isCurrentActiveTier ? 'renovação' : 'aquisição'} de{' '}
                      <strong>{tier.name}</strong> por <strong>{tier.priceGold} Gold</strong> (7 dias)?
                    </p>
                    <div className="vip-confirm-buttons">
                      <button
                        type="button"
                        className="vip-btn vip-btn--secondary"
                        onClick={handleCancelConfirm}
                        disabled={isSubmitting}
                      >
                        Cancelar
                      </button>
                      <button
                        type="button"
                        className="vip-btn vip-btn--primary"
                        onClick={() => handleConfirmPurchase(tier)}
                        disabled={isSubmitting}
                      >
                        {isSubmitting ? 'Processando...' : 'Confirmar'}
                      </button>
                    </div>
                  </div>
                ) : (
                  <button
                    type="button"
                    className="vip-btn vip-btn--cta"
                    disabled={isTierDisabled}
                    onClick={() => handleOpenConfirm(tier.id)}
                    aria-label={
                      isCurrentActiveTier
                        ? `Renovar plano ${tier.name}`
                        : `Comprar plano ${tier.name}`
                    }
                  >
                    {isCurrentActiveTier
                      ? 'Renovar (+7 dias)'
                      : isOtherTierActive
                      ? 'Disponível após expiração'
                      : 'Comprar'}
                  </button>
                )}
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
}
```

